def dehydrate_point(value):
    """
    Dehydrator for Point data.

    The function attempts to convert a Point instance into a JSON‑serialisable
    representation (tuple or dictionary).  It is tolerant of different
    kinds of input:

    * ``None``  → returns ``None``
    * sequence (tuple/list/tuple-like) of length 2 or 3 → returns the same sequence
    * object exposing ``x`` and ``y`` attributes → returns ``(x, y)`` or ``(x, y, z)``
      if a ``z`` attribute is present
    * other objects → string representation

    If any exception occurs during the conversion (for example the object does
    not expose the expected attributes or the sequence is of incorrect
    length) an informative :class:`ValueError` is raised.
    """
    # Handle a missing value
    if value is None:
        return None

    try:
        # Case 1: a sequence that likely already represents a point
        if isinstance(value, (tuple, list)):
            if len(value) in (2, 3):
                # Convert to tuple to avoid accidental mutation
                return tuple(value)
            raise TypeError(f"Sequence of length {len(value)} is not a valid point")

        # Case 2: an object with x and y attributes (and possibly z)
        if hasattr(value, "x") and hasattr(value, "y"):
            coords = [getattr(value, "x"), getattr(value, "y")]
            if hasattr(value, "z"):
                coords.append(getattr(value, "z"))
            return tuple(coords)

        # Fall back: return the string representation (most generic)
        return str(value)

    except Exception as exc:
        # Provide a clear error message so callers can debug
        raise ValueError(f"Unable to dehydrate point: {exc}") from exc

def keys(self):
    """Return the keys of the record.

    :return: list of key names
    """
    try:
        # First, try to use a dedicated attribute that stores record data
        if hasattr(self, "data") and isinstance(self.data, dict):
            return list(self.data.keys())
        # Next, fall back to the instance's __dict__ if available
        attrs = getattr(self, "__dict__", {})
        if isinstance(attrs, dict):
            # Exclude private and protected attributes
            return [key for key in attrs.keys() if not key.startswith("_")]
        # If no data structure is found, return an empty list
        return []
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers, keyed by version tuple.
        If an explicit protocol version is provided, the dictionary will contain either
        zero or one items, depending on whether that version is supported. If no
        protocol version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol version
                                 (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all relevant
                 and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Default mapping of supported protocol versions to handler classes.
        # This attribute should be defined on subclasses or the base class.
        # If it is missing or not a dictionary, we treat it as an empty mapping.
        try:
            handlers_map = getattr(cls, "_protocol_handlers", {})
            if not isinstance(handlers_map, dict):
                handlers_map = {}
        except Exception:
            handlers_map = {}

        # Without a requested version, return a copy of the full mapping
        if protocol_version is None:
            return dict(handlers_map)

        # Validate the requested protocol version
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple of ints, not {type(protocol_version).__name__}"
            )

        # Return either a single-item dict or an empty dict
        if protocol_version in handlers_map:
            return {protocol_version: handlers_map[protocol_version]}
        return {}

def index(self, key):
    """Return the index of the specified key by iterating over self.

    Raises:
        TypeError: If ``self`` is not iterable.
        ValueError: If ``key`` is not found in ``self``.
    """
    try:
        for idx, item in enumerate(self):
            if item == key:
                return idx
    except TypeError as exc:
        raise TypeError("the container must be iterable") from exc
    raise ValueError(f"{key!r} is not in the container")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Default: return all values preserving order
    if not keys:
        try:
            # Try to iterate over items; this should be efficient for
            # typical dict-like objects
            return [value for _, value in self.items()]
        except AttributeError as err:
            raise RuntimeError(
                "The object does not provide an 'items()' method "
                f"required for 'values()': {err}"
            ) from err

    result = []
    # Helper: attempt to convert list of items once for index resolution
    try:
        items_list = list(self.items())
    except AttributeError as err:
        raise RuntimeError(
            "The object does not provide an 'items()' method "
            f"required for indexed lookups: {err}"
        ) from err

    for key in keys:
        if isinstance(key, int):
            # Index lookup
            try:
                result.append(items_list[key][1])
            except IndexError as err:
                raise KeyError(
                    f"Index {key} is out of bounds for the record."
                ) from err
        else:
            # Key lookup
            try:
                result.append(self[key])
            except KeyError as err:
                raise KeyError(
                    f"Key {key!r} not found in the record."
                ) from err
            except Exception as err:
                # Any other issue retrieving by key
                raise RuntimeError(
                    f"Failed to retrieve value for key {key!r}: {err}"
                ) from err
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Attempt to obtain the record's field names and values.
    # Allow for common attribute naming variations.
    keys_list = getattr(self, '_keys', None) or getattr(self, 'keys', None)
    values_list = getattr(self, '_values', None) or getattr(self, 'values', None)

    if keys_list is None or values_list is None:
        raise AttributeError("Record object must have attributes '_keys'/'keys' and '_values'/'values'")

    if len(keys) == 0:
        # Return all field-value pairs.
        return dict(zip(keys_list, values_list))

    result = {}
    for k in keys:
        if isinstance(k, int):
            # Index-based selection.
            if k < 0 or k >= len(keys_list):
                raise IndexError(f"Index {k} out of bounds")
            result[keys_list[k]] = values_list[k]
        else:
            # Key name based selection.
            if k in keys_list:
                idx = keys_list.index(k)
                result[k] = values_list[idx]
            else:
                # Key not found: use None.
                result[k] = None
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    try:
        if not hasattr(self, "data") or not isinstance(self.data, (list, bytearray, bytes)):
            raise TypeError("Expected instance to have a 'data' attribute of type list, bytearray, or bytes")

        # Ensure there are at least two bytes to pop
        if len(self.data) < 2:
            raise IndexError("Not enough data to pop 2 bytes")

        # Extract the last two bytes
        if isinstance(self.data, bytes):
            # bytes are immutable, convert to bytearray for deletion
            last_two = self.data[-2:]
            self.data = bytearray(self.data[:-2])
        else:
            last_two = self.data[-2:]
            del self.data[-2:]

        # Convert to integer (big-endian)
        return int.from_bytes(last_two, byteorder="big", signed=False)

    except Exception as exc:
        # Re-raise with a clearer message
        raise RuntimeError(f"Failed to pop u16: {exc}") from exc

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
           db=None, imp_user=None, dehydration_hooks=None,
           hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
                Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
                Requires Bolt 4.4+
    :param dehydration_hooks:
                Hooks to dehydrate types (dict from type (class) to dehydration
                function). Dehydration functions receive the value and returns an
                object of type understood by packstream.
    :param hydration_hooks:
                Hooks to hydrate types (mapping from type (class) to
                dehydration function). Dehydration functions receive the value of
                type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate input arguments
    try:
        if mode is not None and mode not in ("READ", "WRITE"):
            raise ValueError("`mode` must be either 'READ' or 'WRITE' if specified")
        if bookmarks is not None:
            try:
                bookmarks = list(bookmarks)
            except TypeError:
                raise TypeError("`bookmarks` must be an iterable of strings")
        if metadata is not None and not isinstance(metadata, dict):
            raise TypeError("`metadata` must be a dictionary")
        if timeout is not None:
            if not isinstance(timeout, (int, float)):
                raise TypeError("`timeout` must be a numeric value")
            if timeout <= 0:
                raise ValueError("`timeout` must be positive")
        if db is not None and not isinstance(db, str):
            raise TypeError("`db` must be a string")
        if imp_user is not None and not isinstance(imp_user, str):
            raise TypeError("`imp_user` must be a string")
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise TypeError("`dehydration_hooks` must be a dictionary")
            for k, v in dehydration_hooks.items():
                if not isinstance(k, type):
                    raise TypeError("Keys of `dehydration_hooks` must be types")
                if not callable(v):
                    raise TypeError("Values of `dehydration_hooks` must be callables")
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise TypeError("`hydration_hooks` must be a dictionary")
            for k, v in hydration_hooks.items():
                if not isinstance(k, type):
                    raise TypeError("Keys of `hydration_hooks` must be types")
                if not callable(v):
                    raise TypeError("Values of `hydration_hooks` must be callables")
    except Exception as exc:
        # Preserve the original exception type with context
        raise ValueError(f"Invalid begin parameters: {exc}") from exc

    # Build the BEGIN message payload
    payload = {}
    if mode is not None:
        payload["mode"] = mode
    if bookmarks is not None:
        payload["bookmarks"] = bookmarks
    if metadata is not None:
        payload["properties"] = metadata
    if timeout is not None:
        payload["timeout"] = timeout
    if db is not None:
        payload["database"] = db
    if imp_user is not None:
        payload["impersonated_user"] = imp_user

    # Append to the outgoing queue
    try:
        if hasattr(self, "_outgoing_queue") and isinstance(self._outgoing_queue, list):
            self._outgoing_queue.append(("BEGIN", payload))
        elif hasattr(self, "write_message") and callable(self.write_message):
            # Fallback to a writer method if queue is not directly accessible
            self.write_message(("BEGIN", payload))
        else:
            raise RuntimeError("Unable to queue BEGIN message: no suitable out‑queue or writer")
    except Exception as e:
        raise RuntimeError(f"Failed to enqueue BEGIN message: {e}") from e

    # Construct a Response object
    try:
        return self.Response(**handlers)
    except Exception:
        # Fallback minimal Response when the class isn't available
        class _SimpleResponse:
            def __init__(self, **h):
                self.handlers = h
            def __repr__(self):
                return f"<SimpleResponse handlers={list(self.handlers)}>"
        return _SimpleResponse(**handlers)

def round_half_to_even(n):
    """
    Round a number to the nearest integer, with half values rounded to the nearest even integer
    (bankers rounding). Works with int, float, or Decimal types. Raises ValueError for invalid inputs.
    """
    try:
        return int(round(n))
    except Exception as exc:
        raise ValueError(f"Invalid input {n!r}: {exc}") from exc

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        # Build cache key based on arguments
        def _make_key(args, kwargs):
            if typed:
                args_key = tuple((arg, type(arg)) for arg in args)
                kw_key = tuple((k, kwargs[k], type(kwargs[k])) for k in sorted(kwargs))
            else:
                args_key = args
                kw_key = tuple((k, kwargs[k]) for k in sorted(kwargs))
            return args_key + kw_key

        def wrapper(*args, **kwargs):
            if maxsize <= 0:
                return func(*args, **kwargs)
            key = _make_key(args, kwargs)
            now = timer()
            entry = cache.get(key)
            if entry is not None:
                value, expires = entry
                if now < expires:
                    # Cache hit; move key to end to mark as recently used
                    cache.pop(key)
                    cache[key] = (value, expires)
                    return value
                else:
                    # Expired entry
                    cache.pop(key)
            # Cache miss or expired; compute new value
            result = func(*args, **kwargs)
            expires_at = now + ttl
            if len(cache) >= maxsize:
                # Remove least-recently used item (first item in insertion order)
                try:
                    oldest_key = next(iter(cache))
                    cache.pop(oldest_key)
                except StopIteration:
                    pass
            cache[key] = (result, expires_at)
            return result

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__wrapped__ = func
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize < 1:
        raise ValueError("maxsize must be a positive integer")

    def decorator(func):
        cache = {}
        usage = {}
        lock = None

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build the cache key while respecting the `typed` flag
            try:
                if typed:
                    key_args = tuple((type(arg), arg) for arg in args)
                    key_kwargs = tuple((k, type(v), v) for k, v in sorted(kwargs.items()))
                else:
                    key_args = args
                    key_kwargs = tuple(sorted(kwargs.items()))
                key = (key_args, key_kwargs)
                # Verify that the key is hashable
                hash(key)
            except Exception as exc:
                raise TypeError("arguments to memoized function must be hashable") from exc

            # Return cached value if present
            if key in cache:
                # Update usage ordering
                usage.pop(key)
                usage[key] = None
                return cache[key]

            # Compute the function result
            result = func(*args, **kwargs)

            # Cache the new result
            cache[key] = result
            usage[key] = None
            # Evict the most recently used entry if cache is full
            if len(cache) > maxsize:
                # MRU eviction: pop the most recent key
                evict_key = next(reversed(usage))
                usage.pop(evict_key)
                cache.pop(evict_key)

            return result

        def cache_info():
            """Report cache statistics"""
            return {"hits": sum(1 for k in cache if k in usage), "misses": len(usage) - sum(1 for k in cache if k in usage)}

        wrapper.cache_info = cache_info
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    if maxsize is not None and (not isinstance(maxsize, int) or maxsize < 0):
        raise TypeError("maxsize must be None or a non-negative integer")
    def decorating_function(user_function):
        cache = {}
        order = []  # list of keys for LRU order, oldest first
        hits = 0
        misses = 0
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            if typed:
                key = (tuple((arg, type(arg)) for arg in args),
                       tuple(sorted((k, v, type(v)) for k, v in kwargs.items())))
            else:
                key = (args, tuple(sorted(kwargs.items())))
            try:
                result = cache[key]
                hits += 1
                # move key to end to mark as recently used
                if key in order:
                    order.remove(key)
                order.append(key)
                return result
            except KeyError:
                misses += 1
                result = user_function(*args, **kwargs)
                if maxsize is not None and maxsize != 0:
                    cache[key] = result
                    order.append(key)
                    if len(order) > maxsize:
                        oldest_key = order.pop(0)
                        del cache[oldest_key]
                return result
        class CacheInfo:
            __slots__ = ('hits', 'misses', 'maxsize', 'currsize')
            def __init__(self, hits, misses, maxsize, currsize):
                self.hits = hits
                self.misses = misses
                self.maxsize = maxsize
                self.currsize = currsize
            def __repr__(self):
                return (f"CacheInfo(hits={self.hits}, misses={self.misses}, "
                        f"maxsize={self.maxsize}, currsize={self.currsize})")
        def cache_info():
            return CacheInfo(hits, misses, maxsize, len(cache))
        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            order.clear()
            hits = misses = 0
        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        wrapper.cache_parameters = lambda: {'maxsize': maxsize, 'typed': typed}
        wrapper.__name__ = user_function.__name__
        wrapper.__doc__ = user_function.__doc__
        wrapper.__module__ = user_function.__module__
        return wrapper
    return decorating_function

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Get the first key inserted
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')

    # Remove the key-value pair from the dictionary
    value = self.pop(first_key)

    return (first_key, value)

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d. d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(fn):
        def wrapper(self, *args, **kwargs):
            # Compute the cache key. If 'key' is callable, use its result;
            # otherwise, fall back to a sensible default based on the
            # function identity and the arguments.
            try:
                if callable(key):
                    cache_key = key(self, *args, **kwargs)
                else:
                    cache_key = key
            except Exception:
                cache_key = (fn, args, tuple(sorted(kwargs.items())))
            # Acquire the optional lock to serialize cache access.
            if lock:
                lock.acquire()
            try:
                if cache_key in cache:
                    return cache[cache_key]
                result = fn(self, *args, **kwargs)
                cache[cache_key] = result
                return result
            finally:
                if lock:
                    lock.release()
        return wrapper
    return decorator

def _reset_logging(cls):
    """
    Reset logging configuration to default settings.
    """
    try:
        import logging
        # Remove all handlers associated with the root logger
        root_logger = logging.getLogger()
        for handler in root_logger.handlers[:]:
            try:
                handler.close()
            except Exception:
                pass
        root_logger.handlers.clear()
        # Reconfigure basic logging
        logging.basicConfig(level=logging.INFO)
    except Exception:
        # Swallow any error to avoid breaking the caller
        pass

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        name = self.__class__.__name__
    except Exception:
        # If self is invalid or does not have a class name, return None
        return None

    suffixes = ("Py", "Fallback")
    for suffix in suffixes:
        if name.endswith(suffix):
            return name[: -len(suffix)]
    return name

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    import os, sys
    try:
        # Disable C optimizations on PyPy because of environment differences
        if sys.implementation.name.lower() == 'pypy':
            return False

        pure_python = os.getenv('PURE_PYTHON')
        if pure_python:
            val = pure_python.strip().lower()
            if val in ('1', 'true', 'yes', 'y', 't', 'on'):
                return False

        return True
    except Exception:
        # In case of any unexpected error, conservatively avoid C optimizations
        return False

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        required = _c_optimizations_required()
        return not required
    except Exception:
        # Default to False if _c_optimizations_required is not defined or raises an exception
        return False

def reset(self):
    """
    Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    try:
        self.context = {}
    except Exception as exc:
        raise RuntimeError(f"Unable to reset histogram context: {exc}") from exc

    # Reinitialize bins
    try:
        # If an `initial_value` attribute is defined and not None,
        # reuse it to rebuild the bins; otherwise fall back to `make_bins()`.
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve current number of bins if they already exist
            if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                bin_count = len(self.bins)
                self.bins = [self.initial_value] * bin_count
            else:
                # If no bins are defined yet, create at least one
                self.bins = [self.initial_value]
        else:
            # Use the factory method to create a fresh set of bins
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                raise AttributeError("Neither `initial_value` nor a callable `make_bins` method is available to reinitialize bins.")
    except Exception as exc:
        raise RuntimeError(f"Unable to reinitialize histogram bins: {exc}") from exc
    return None

def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        try:
            if not isinstance(separator, str):
                raise TypeError("Separator must be a string.")
            lines = []
            if header is not None:
                lines.append(str(header))
            points = getattr(self, "points", None)
            if points is None:
                return "\n".join(lines)
            for point in points:
                try:
                    coord, value = point[0], point[1]
                except Exception:
                    # Fallback for dict-like points
                    if isinstance(point, dict):
                        items = list(point.items())
                        if not items:
                            continue
                        coord, value = items[0][0], items[0][1]
                    else:
                        continue
                # Convert coordinate to string
                if hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes)):
                    coord_str = separator.join(str(c) for c in coord)
                else:
                    coord_str = str(coord)
                # Convert value parts to string
                if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
                    value_str = separator.join(str(v) for v in value)
                else:
                    value_str = str(value)
                lines.append(f"{coord_str}{separator}{value_str}")
        except Exception:
            raise
        return "\n".join(lines)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Quick exit for None
    if seq is None:
        return False

    # Helper to get the class name without importing any modules
    def _type_name(obj):
        try:
            return obj.__class__.__name__
        except Exception:
            return ''

    # If seq itself is a Source instance, disallow
    if _type_name(seq) == 'Source':
        return False

    # If seq is a single FillRequest, accept
    if _type_name(seq) == 'FillRequest':
        return True

    # Try to iterate over seq if it is an iterable but not a string/bytes
    try:
        if isinstance(seq, (list, tuple, set)):
            for item in seq:
                if _type_name(item) == 'FillRequest':
                    return True
            return False
        # Fallback: check for __iter__ but avoid strings/bytes
        if hasattr(seq, '__iter__') and not isinstance(seq, (str, bytes)):
            for item in seq:
                if _type_name(item) == 'FillRequest':
                    return True
            return False
    except Exception:
        return False

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill')) and callable(getattr(obj, 'request'))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        attribute = getattr(obj, 'run')
    except Exception:
        return False
    else:
        return callable(attribute)

def is_fill_compute_el(obj):
    """
    Return True if `obj` has executable methods named 'fill' and 'compute'.
    The methods must be present and callable; otherwise return False.
    """
    try:
        fill = getattr(obj, 'fill')
        compute = getattr(obj, 'compute')
    except AttributeError:
        return False
    return callable(fill) and callable(compute)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1, if a key is present both in *d1* and *d2*
    but has different values, it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate input types
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")
    if level < -1:
        raise ValueError("level must be -1 (infinite) or a non-negative integer")

    # Helper to deep copy values
    def _deepcopy(value):
        if isinstance(value, dict):
            return {k: _deepcopy(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_deepcopy(v) for v in value]
        elif isinstance(value, tuple):
            return tuple(_deepcopy(v) for v in value)
        elif isinstance(value, set):
            return {_deepcopy(v) for v in value}
        else:
            return value

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # Key unique to d1: copy it
            result[key] = _deepcopy(val1)
        else:
            val2 = d2[key]
            # If both values are dicts and we can recurse:
            if isinstance(val1, dict) and isinstance(val2, dict) and (level != 0):
                # Determine next recursion level
                next_level = level - 1 if level > 0 else -1
                sub_diff = difference(val1, val2, level=next_level)
                if sub_diff:
                    result[key] = sub_diff
            else:
                # If values differ (including type mismatch), include val1
                if val1 != val2:
                    result[key] = _deepcopy(val1)
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored."""
    try:
        # Convert coordinate to a NumPy array of floats
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise ValueError(f"Invalid coordinate type: {coord}") from exc

    # Ensure the histogram has defined edges
    if not hasattr(self, "edges") or not self.edges:
        raise RuntimeError("Histogram edges are not defined.")

    ndim = len(self.edges)
    if coord_arr.ndim == 0:
        if ndim != 1:
            raise ValueError(f"Coordinate dimension mismatch: expected {ndim}D, got scalar")
        coord_arr = np.array([coord_arr])

    if coord_arr.size != ndim:
        raise ValueError(f"Coordinate dimension mismatch: expected {ndim}D, got {coord_arr.shape}")

    # Validate weight
    try:
        w = float(weight)
    except Exception as exc:
        raise ValueError(f"Weight must be numeric, got {weight}") from exc
    if not np.isfinite(w):
        raise ValueError(f"Weight must be finite, got {weight}")

    # Compute bin indices for each axis
    bin_indices = []
    for axis in range(ndim):
        try:
            idx = np.searchsorted(self.edges[axis], coord_arr[axis], side='right') - 1
        except Exception as exc:
            raise RuntimeError(f"Error computing bin index on axis {axis}") from exc
        # Check bounds
        if idx < 0 or idx >= len(self.edges[axis]) - 1:
            # Coordinate is outside the histogram edges; ignore
            return
        bin_indices.append(idx)

    # Increment the histogram bin
    try:
        self.contents[tuple(bin_indices)] += w
    except Exception as exc:
        raise RuntimeError("Failed to update histogram content") from exc

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest,
    observer_schema,
    response,
):
    """Recursively updates a partial ``last_applied_manifest`` list from a Kubernetes response.

    Parameters
    ----------
    last_applied_manifest : list
        Partial ``last_applied_manifest`` being updated. Elements can be primitives, dicts, or lists.
    observer_schema : list | dict
        Schema information describing the expected structure of each element. If a dict is provided,
        it is treated as a repeating schema for all list items.
    response : list
        Partial response from the Kubernetes API.

    Returns
    -------
    list
        The updated ``last_applied_manifest``.

    Notes
    -----
    * The function extends ``last_applied_manifest`` with ``None`` entries if it is shorter than
      ``response``.
    * Scalar values are copied only when the corresponding slot in
      ``last_applied_manifest`` is ``None`` or missing.
    * For nested dictionaries and lists the update is performed recursively by calling
      ``update_last_applied_manifest_dict_from_resp`` and this function itself.
    """

    # Basic type validation
    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(response, list):
        raise TypeError(
            f"response must be a list, got {type(response).__name__}"
        )

    # Normalise observer_schema to a list form
    if isinstance(observer_schema, dict):
        # Assume schema applies to all items equally
        observer_schema = [observer_schema]
    elif not isinstance(observer_schema, list):
        raise TypeError(
            f"observer_schema must be a list or dict, got {type(observer_schema).__name__}"
        )

    # Ensure the local list is long enough
    max_len = max(len(last_applied_manifest), len(response))
    while len(last_applied_manifest) < max_len:
        last_applied_manifest.append(None)

    # Perform the update
    for idx, resp_item in enumerate(response):
        try:
            existing_item = last_applied_manifest[idx]
        except IndexError:
            existing_item = None

        # Determine the schema element to use for this index
        if idx < len(observer_schema):
            schema_item = observer_schema[idx]
        else:
            # Default to the last schema item if index exceeds length
            schema_item = observer_schema[-1] if observer_schema else {}

        # If the current slot is empty, set it directly (with recursive handling)
        if existing_item is None:
            if isinstance(resp_item, dict):
                # Ensure dictionary slot exists
                if not isinstance(last_applied_manifest[idx], dict):
                    last_applied_manifest[idx] = {}
                # Recursively update the dictionary
                try:
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[idx],
                        schema_item.get("properties", []),
                        resp_item,
                    )
                except Exception as exc:
                    msg = f"Failed to update dict at index {idx}"
                    raise RuntimeError(msg) from exc
            elif isinstance(resp_item, list):
                # Ensure list slot exists
                if not isinstance(last_applied_manifest[idx], list):
                    last_applied_manifest[idx] = []
                # Recursively update the list
                try:
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[idx],
                        schema_item.get("items", []),
                        resp_item,
                    )
                except Exception as exc:
                    msg = f"Failed to update list at index {idx}"
                    raise RuntimeError(msg) from exc
            else:
                # Primitive value; copy as is
                last_applied_manifest[idx] = resp_item
        else:
            # Existing value present: merge recursively if appropriate
            if isinstance(existing_item, dict) and isinstance(resp_item, dict):
                try:
                    update_last_applied_manifest_dict_from_resp(
                        existing_item,
                        schema_item.get("properties", []),
                        resp_item,
                    )
                except Exception as exc:
                    msg = f"Failed to merge dict at index {idx}"
                    raise RuntimeError(msg) from exc
            elif isinstance(existing_item, list) and isinstance(resp_item, list):
                try:
                    update_last_applied_manifest_list_from_resp(
                        existing_item,
                        schema_item.get("items", []),
                        resp_item,
                    )
                except Exception as exc:
                    msg = f"Failed to merge list at index {idx}"
                    raise RuntimeError(msg) from exc
            else:
                # For primitives, we leave the existing value unchanged
                pass

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema.
    """
    try:
        # Basic validation of the expected structure
        if not hasattr(app, "spec"):
            raise ValueError("The application object does not have a 'spec' attribute.")
        if not hasattr(app.spec, "manifest"):
            raise ValueError("The application spec does not contain a 'manifest' attribute.")
        if not isinstance(app.spec.manifest, (list, tuple)):
            raise ValueError("The 'manifest' attribute should be a list or tuple of resources.")

        # Retrieve any user‑defined observer schema to avoid overwriting it
        custom_schema = getattr(app.spec, "observer_schema", {})
        if custom_schema is None:
            custom_schema = {}

        default_schema = {}
        for item in app.spec.manifest:
            # Each item should be a dict representing a Kubernetes resource
            if not isinstance(item, dict):
                continue
            kind = item.get("kind")
            if not kind:
                # Skip items that do not specify a kind
                continue

            # Skip if a custom schema is already defined for this kind
            if isinstance(custom_schema, dict) and kind in custom_schema:
                continue

            # Build a lightweight default schema based on the resource's spec
            # (This can be adapted to meet the exact schema format required)
            spec_payload = item.get("spec", {})
            default_schema[kind] = spec_payload

        return default_schema

    except Exception as exc:
        # Re‑raise the exception with an informative message
        raise RuntimeError("Failed to generate default observer schema") from exc

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        status = getattr(self, 'status')
        return f"{str(prefix)}{str(status)}"
    except Exception:
        return str(prefix) + "unknown"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Ensure the prefix is a string
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")

    try:
        # Attempt to locate a log attribute in the instance
        log = None
        for attr in ('validation_log', 'log', '_validation_log', '_log'):
            if hasattr(self, attr):
                log = getattr(self, attr)
                break

        # If no log found, return empty string
        if log is None:
            return ''

        # If the log is a single string, prepend the prefix
        if isinstance(log, str):
            return prefix + log

        # If the log is an iterable (e.g. list or tuple)
        if hasattr(log, '__iter__') and not isinstance(log, (bytes, bytearray)):
            lines = []
            for item in log:
                # Convert Exceptions to readable string
                if isinstance(item, Exception):
                    message = f"{item.__class__.__name__}: {item}"
                else:
                    message = str(item)
                lines.append(prefix + message)
            return "\n".join(lines)

        # Fallback to string conversion for non-iterable objects
        return prefix + str(log)

    except Exception as exc:
        # In case of unexpected errors, return an informative message
        return f"{prefix}Error generating status: {exc}"

def check_digests_present_and_used(self, manifest_files, digests_used):
        """
        Check all digests in manifest that are needed are present and used.

        Parameters
        ----------
        manifest_files : dict or list
            Mapping of expected digest file names to metadata or a list of
            dictionaries containing a `'digest_file'` key. If a dictionary is
            provided, its keys are treated as the digest file names.
        digests_used : iterable
            Iterable of digest file names that have been utilized.

        Raises
        ------
        ValueError
            - If there are expected digests not present in `digests_used`.
            - If there are digests in `digests_used` that are not part of the
              expected set derived from `manifest_files`.
        """
        # Normalize expected digests
        try:
            if isinstance(manifest_files, dict):
                expected = set(manifest_files.keys())
            elif isinstance(manifest_files, (list, set, tuple)):
                expected = set()
                for entry in manifest_files:
                    # Expect each entry to be a dict with a 'digest_file' key
                    if isinstance(entry, dict) and 'digest_file' in entry:
                        expected.add(entry['digest_file'])
                    else:
                        raise ValueError(
                            f"Unsupported manifest entry type or missing 'digest_file': {entry}"
                        )
            else:
                raise ValueError(
                    f"Unsupported manifest_files type: {type(manifest_files)}"
                )
        except Exception as exc:
            raise ValueError(f"Error processing manifest_files: {exc}") from exc

        # Normalize used digests
        try:
            used = set(digests_used or [])
        except Exception as exc:
            raise ValueError(f"Error processing digests_used: {exc}") from exc

        missing = expected - used
        unused = used - expected

        errors = []
        if missing:
            errors.append(f"Missing digests: {sorted(missing)}")
        if unused:
            errors.append(f"Unused digests: {sorted(unused)}")

        if errors:
            raise ValueError("; ".join(errors))

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input
    if inventory is None or not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping versions to lists of entries")

    if version not in inventory:
        raise ValueError(f"Specified version '{version}' not found in inventory")

    # Determine order of versions: assume keys are sortable (e.g., strings or numbers)
    try:
        sorted_versions = sorted(inventory.keys(), key=lambda v: (v is not None, v))
    except TypeError:
        # If versions cannot be sorted, fall back to insertion order
        sorted_versions = list(inventory.keys())

    # Find index of requested version
    try:
        start_index = sorted_versions.index(version)
    except ValueError:
        raise ValueError(f"Specified version '{version}' not present in inventory keys")

    # Build mapping from logical path to set of content files
    path_map = {}

    # Iterate over versions from requested onward
    for ver in sorted_versions[start_index:]:
        entries = inventory.get(ver, [])
        if not isinstance(entries, list):
            # Skip invalid entries
            continue
        for entry in entries:
            try:
                # Support entry as dict or tuple/list
                if isinstance(entry, dict):
                    logical_path = entry.get("logical_path") or entry.get("logical_path_in_state")
                    content_file = entry.get("content_file") or entry.get("content_file_path")
                else:
                    # Assume tuple/list format (logical_path, content_file)
                    logical_path, content_file = entry[0], entry[1]
            except Exception:
                continue  # Skip malformed entry

            if logical_path is None or content_file is None:
                continue
            if logical_path not in path_map:
                path_map[logical_path] = set()
            path_map[logical_path].add(content_file)

    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    errors = []

    try:
        available_files = set(manifest_files) if manifest_files is not None else set()

        if fixity is None:
            # Nothing to validate – treat as valid.
            return

        if isinstance(fixity, dict):
            # Support either a mapping ``filename -> attributes`` or a
            # mapping ``filename -> checksum`` style.  In both cases the keys
            # are filenames.
            for fname, attrs in fixity.items():
                if fname not in available_files:
                    errors.append(f"Unknown file referenced in fixity: '{fname}'")
                # If the value is a mapping, we should check that it contains
                # at least a 'checksum' key.
                if isinstance(attrs, dict):
                    if 'checksum' not in attrs and 'value' not in attrs:
                        errors.append(
                            f"Missing checksum entry for file '{fname}' in fixity block"
                        )
                else:
                    # If the value is not a mapping, we can only check that it
                    # looks like a checksum string (e.g., not empty).
                    if not isinstance(attrs, str) or not attrs.strip():
                        errors.append(
                            f"Invalid checksum value for file '{fname}' in fixity block"
                        )
        elif isinstance(fixity, list):
            # List of dicts, e.g. [{'name': 'foo.txt', 'checksum': 'abc'}, ...]
            for item in fixity:
                if not isinstance(item, dict):
                    errors.append(f"Fixity list item not a dict: {item!r}")
                    continue
                fname = item.get('name')
                if fname is None:
                    errors.append(f"Missing 'name' key in fixity item: {item!r}")
                    continue
                if fname not in available_files:
                    errors.append(f"Unknown file referenced in fixity: '{fname}'")
                if 'checksum' not in item and 'value' not in item:
                    errors.append(
                        f"Missing checksum for file '{fname}' in fixity block"
                    )
        else:
            errors.append(
                f"Invalid type for fixity block: expected dict or list, got {type(fixity).__name__}"
            )

        if errors:
            raise ValueError("Fixity validation failed:\n- " + "\n- ".join(errors))

    except Exception as exc:
        # Any unexpected error is re-raised as a ValueError with a readable
        # message so that callers do not have to deal with internal types.
        raise ValueError(f"Error validating fixity: {exc}") from exc

def files_list(path):
    """
    Return the files in `path`
    """
    if not isinstance(path, str):
        return []
    try:
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except Exception:
        return []

def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : Any
        Placeholder for source context (not used in grouping logic).
    xmls : list
        List of XML file paths.
    files : list
        List of all file paths in the folder or zipfile.

    Returns
    -------
    dict
        Mapping from the XML basename to a list of file paths that share that basename.
    """
    def _basename(path):
        # extract base name without extension, handling both '/' and '\\' separators
        if not isinstance(path, str) or path == "":
            return ""
        # find last path separator
        for sep in ('/', '\\'):
            if sep in path:
                path = path.rsplit(sep, 1)[-1]
        # remove extension
        if '.' in path:
            return path.rsplit('.', 1)[0]
        return path

    result = {}
    try:
        # Normalise inputs
        xmls = xmls or []
        files = files or []

        # Precompute mapping of file basenames to file paths
        file_map = {}
        for f in files:
            if not isinstance(f, str):
                continue
            bn = _basename(f)
            file_map.setdefault(bn, []).append(f)

        for xml in xmls:
            if not isinstance(xml, str):
                continue
            xml_base = _basename(xml)
            # Lookup files with matching base name
            matched = file_map.get(xml_base, [])
            if matched:
                result[xml_base] = matched
    except Exception:
        # In case of unexpected errors, return an empty dictionary
        return {}
    return result

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """

    # Basic input validation
    if not basename or not file_path:
        raise ValueError("Both 'basename' and 'file_path' must be provided and non-empty.")

    if not isinstance(basename, str) or not isinstance(file_path, str):
        raise TypeError("Both 'basename' and 'file_path' must be strings.")

    # Ensure the asset storage dictionary exists
    if not hasattr(self, "assets") or not isinstance(self.assets, dict):
        self.assets = {}

    # Add or update the asset mapping
    try:
        self.assets[basename] = file_path
    except Exception as exc:
        raise RuntimeError(f"Failed to add asset for '{basename}': {exc}") from exc

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        # Re-raise any unexpected error as ValueError
        raise ValueError(f"An error occurred while processing the content: {e}") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    Busca em cada XPath fornecido pelo `pubdate_xpaths` na árvore `node` e devolve o primeiro
    resultado não vazio encontrado. Se nenhum XPath produzir um resultado válido,
    None é retornado.

    Parameters
    ----------
    node : object
        Um objeto de nó que suporte o método `xpath`. Em geral, ele deve ser um
        elemento do lxml ou de outra biblioteca de processamento XML/HTML.
    pubdate_xpaths : list[str]
        Lista de strings contendo expressões XPath onde a data de publicação pode
        ser encontrada.

    Returns
    -------
    str | None
        O valor textual da primeira correspondência encontrada, ou None se nenhuma
        data for localizada ou ocorrer algum erro durante a avaliação.

    Raises
    ------
    None
        Todos os erros são capturados internamente e resultam em retorno de None.
    """
    # Valida tipos de entrada de forma permissiva
    if node is None or not hasattr(node, "xpath"):
        return None
    if not isinstance(pubdate_xpaths, (list, tuple)):
        return None

    # Itera pelas expressões XPath tentando encontrar a primeira ocorrência válida
    for xpath_expr in pubdate_xpaths:
        if not isinstance(xpath_expr, str):
            continue
        try:
            results = node.xpath(xpath_expr)
        except Exception:
            # Ignora erros de avaliação de XPath
            continue

        if not results:
            continue

        # Tenta extrair um valor string de cada resultado possível
        for item in results:
            # Se o item já for uma string, devolve-o direto
            if isinstance(item, str):
                return item.strip()
            # Caso seja um elemento XML/HTML, use .text
            try:
                if hasattr(item, "text"):
                    text = getattr(item, "text")
                    if isinstance(text, str) and text.strip():
                        return text.strip()
                # Em algumas bibliotecas pode existir .text_content()
                if hasattr(item, "text_content"):
                    text = getattr(item, "text_content")()
                    if isinstance(text, str) and text.strip():
                        return text.strip()
            except Exception:
                continue

    # Se nenhuma correspondência for válida, devolve None
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    if issue is None:
        return (None, None)
    try:
        # Extract text from element or convert directly to string
        if isinstance(issue, str):
            text = issue
        elif hasattr(issue, 'text'):
            text = issue.text
        else:
            text = str(issue)
    except Exception:
        return (None, None)

    # Normalize text
    text = text.strip().lower()
    # Remove surrounding parentheses and dots
    text = text.replace('(', ' ').replace(')', ' ')
    text = text.replace('.', ' ')
    text = text.replace(',', ' ')
    # Collapse multiple spaces
    import re
    text = re.sub(r'\s+', ' ', text).strip()

    number = None
    suppl = None

    # Search for a numeric part (possibly a range like 2-5)
    number_match = re.search(r'\d+(?:-\d+)?', text)
    if number_match:
        num_str = number_match.group()
        # Convert to int if no hyphen
        if '-' not in num_str:
            try:
                number = int(num_str)
            except ValueError:
                number = num_str
        else:
            number = num_str  # keep as string for ranges
        # Extract the supplement part after the number
        suppl_raw = text[number_match.end():].strip()
        # If nothing after number, look before number for supplement terms
        if not suppl_raw:
            suppl_raw = text[:number_match.start()].strip()
        # Clean up any stray tags or fragments
        suppl_raw = re.sub(r'\b(?:s|suppl|supp|spe|pr)\b', '', suppl_raw)
        suppl_raw = suppl_raw.strip()
        suppl = suppl_raw if suppl_raw else None
    else:
        # No numeric part found, try to identify SUPPL or SPE keywords
        sup_keywords = ['suppl', 'supp', 'spe', 'pr']
        found = [kw for kw in sup_keywords if kw in text]
        if found:
            suppl = ' '.join(found)
        else:
            suppl = None

    return (number, suppl)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    The output is human‑readable and recursively shows nested
    containers and objects that expose ``__dict__`` or ``__slots__``.
    If *debug* is true, the type name is included next to each value.
    The function is resilient to self‑referencing structures.
    """
    seen = set()

    def _repr(obj, cur_indent):
        # Avoid infinite recursion for cyclic references
        obj_id = id(obj)
        if obj_id in seen:
            return '<recursion>'
        seen.add(obj_id)

        # Simple primitive types
        if isinstance(obj, (int, float, complex, bool)):
            result = str(obj)
        elif isinstance(obj, str):
            result = repr(obj)
        elif isinstance(obj, bytes):
            result = repr(obj)
        # Containers
        elif isinstance(obj, (list, tuple, set, frozenset)):
            prime = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
            closing = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
            inner = ',\n'.join(
                _repr(v, cur_indent + 4) for v in obj
            )
            spacer = ' ' * (cur_indent + 4)
            result = f"{prime}\n{spacer}{inner}\n{' ' * cur_indent}{closing}"
        elif isinstance(obj, dict):
            inner = ',\n'.join(
                f"{_repr(k, cur_indent + 4)}: {_repr(v, cur_indent + 4)}"
                for k, v in obj.items()
            )
            spacer = ' ' * (cur_indent + 4)
            result = f"{{\n{spacer}{inner}\n{' ' * cur_indent}}}"
        # Objects with attributes
        else:
            attrs = getattr(obj, "__dict__", None)
            if attrs is None:
                attrs = {}
            if isinstance(attrs, dict):
                items = attrs.items()
            else:  # __slots__ scenario
                items = ((slot, getattr(obj, slot)) for slot in attrs)
            parts = []
            for name, val in items:
                part = f"{name}={_repr(val, cur_indent + 4)}"
                parts.append(part)
            inner = ',\n'.join(' ' * (cur_indent + 4) + p for p in parts)
            result = f"{obj.__class__.__name__}(\n{' ' * (cur_indent + 4)}{inner}\n{' ' * cur_indent})"

        # Debug mode: prefix type information
        if debug:
            if not (isinstance(obj, (int, float, complex, bool, str, bytes))):
                result = f"<{type(obj).__name__}>{result}"

        return result

    return _repr(self, indent)

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate that the hook is hashable so it can be used as a dictionary key
    try:
        hash(hook)
    except TypeError:
        raise TypeError(f"Hook {hook!r} must be hashable.") from None

    # Ensure the registry exists on the instance
    if not hasattr(self, "_registry"):
        self._registry = {}

    def decorator(func):
        if not callable(func):
            raise TypeError(f"Listener must be callable, got {type(func).__name__}.")
        # Register the function under the specified hook
        self._registry.setdefault(hook, []).append(func)
        return func

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        name = namefunc(*args, **kwargs)
        if name is None:
            return None
        try:
            # If running under Python 2, unicode type exists
            if isinstance(name, unicode):
                return name.encode('utf-8')
        except NameError:
            # Running under Python 3: no conversion needed
            pass
        return name
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Default fallback information
    default = {"version": "0+unknown", "full-revisionid": ""}
    # Try to import the modern importlib.metadata (py3.8+)
    try:
        from importlib.metadata import version as _version, PackageNotFoundError
    except ImportError:
        # Fall back to the backport for older Python versions
        try:
            from importlib_metadata import version as _version, PackageNotFoundError
        except ImportError:
            # Unable to import metadata utilities; return default
            return default

    # Determine a candidate package name.  __package__ is often more accurate
    # than __name__ in modules.  If it is None or __main__, fall back to the
    # current working directory's basename.
    pkg = __package__ or __name__
    if not pkg or pkg == "__main__":
        import os, sys
        pkg = os.path.basename(os.getcwd())
        # If the package name ends with the script extension, strip it
        if pkg.endswith(".__init__"):
            pkg = pkg.rsplit(".", 1)[0]

    # Attempt to fetch the distribution's version string
    try:
        ver = _version(pkg)
    except PackageNotFoundError:
        return default

    # Try to determine the full revision ID (e.g., git commit SHA)
    rev = ""
    try:
        import subprocess, os
        # Find the git directory by walking up from the current path
        root = os.getcwd()
        while root and os.path.isdir(root) and not os.path.isdir(os.path.join(root, ".git")):
            root = os.path.dirname(root)
        if root and os.path.isdir(os.path.join(root, ".git")):
            git_dir = os.path.join(root, ".git")
            # Read the HEAD file to find the current ref or commit
            head_path = os.path.join(git_dir, "HEAD")
            with open(head_path, encoding="utf-8") as fh:
                content = fh.read().strip()
            if content.startswith("ref:"):
                ref_path = os.path.join(git_dir, content.partition(" ")[2])
                with open(ref_path, encoding="utf-8") as fh:
                    rev = fh.read().strip()
            else:
                rev = content
    except Exception:
        # Fail silently – rev remains empty
        pass

    return {"version": ver, "full-revisionid": rev}

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        has_plus = False
        for piece in pieces:
            if piece == '+':
                has_plus = True
                break
    except Exception:
        # If pieces is not iterable or any error occurs, assume no plus present
        return '+'
    return '.' if has_plus else '+'

def get_config():
    """Create, populate and return the VersioneerConfig() object."""
    try:
