def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Attempt to use required modules; fail gracefully if not available
    try:
        root = getattr(self, 'root_path')
    except AttributeError:
        if show_warnings:
            print("Warning: instance has no 'root_path' attribute")
        return (0, 0)

    if not root or not os.path.isdir(root):
        if show_warnings:
            print(f"Warning: root_path '{root}' is not a valid directory")
        return (0, 0)

    num_objects = 0
    good_objects = 0

    # If digests are to be checked, try to obtain the expected digest mapping
    expected_digests = getattr(self, 'expected_digests', {})
    for dirpath, _, filenames in os.walk(root):
        for name in filenames:
            num_objects += 1
            path = os.path.join(dirpath, name)
            valid = True
            try:
                # Validate existence
                if validate_objects and not os.path.isfile(path):
                    valid = False

                # Validate digest if requested
                if check_digests:
                    # If an expected digest is available for this file, verify it
                    expected = expected_digests.get(path)
                    if expected is not None:
                        # Compute actual SHA‑256 digest
                        h = hashlib.sha256()
                        with open(path, 'rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                h.update(chunk)
                        actual = h.hexdigest()
                        if actual != expected:
                            valid = False
            except Exception as exc:
                if show_warnings:
                    print(f"Warning: error validating '{path}': {exc}")
                valid = False

            if valid:
                good_objects += 1

    return (num_objects, good_objects)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if not isinstance(version, str):
            raise TypeError("version must be a string")
        if version == "":
            return ""
        parts = version.split(".")
        # Find the last numeric part to increment
        last = parts[-1]
        if not last.isdigit():
            raise ValueError(f"Invalid numeric component: {last!r}")
        increment = int(last) + 1
        width = len(last)
        new_last = str(increment).zfill(width)
        # If the incremented number grows in length, keep the longer number
        if len(new_last) > width:
            new_last = str(increment)
        parts[-1] = new_last
        return ".".join(parts)
    except Exception as e:
        raise ValueError(f"Cannot compute next version from {version!r}") from e

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    Parameters
    ----------
    nodes : list
        A list of two-element tuples (key_node, value_node).

    Returns
    -------
    list
        A list of tuples with all duplicate top-level keys merged.

    Raises
    ------
    TypeError
        If the input is not a list of two-element tuples or if individual nodes do not
        provide the expected attributes.
    '''
    if not isinstance(nodes, list):
        raise TypeError('Input must be a list of (key_node, value_node) tuples')

    def _is_mapping(node):
        # Treat node as a mapping if it has a 'value' attribute that is a list.
        return hasattr(node, 'value') and isinstance(node.value, list)

    def _merge_mapping_values(existing_node, new_node):
        """
        Merge two ruamel.yaml MappingNode values in place.
        `existing_node` will be modified to contain the merged mapping.
        """
        existing_dict = {}
        for k_node, v_node in existing_node.value:
            existing_dict[k_node.value] = (k_node, v_node)

        for k_node, v_node in new_node.value:
            key = k_node.value
            if key in existing_dict:
                existing_k, existing_v = existing_dict[key]
                if _is_mapping(existing_v) and _is_mapping(v_node):
                    _merge_mapping_values(existing_v, v_node)
                    # Keep the new key node for the key; the value node is already merged
                    existing_dict[key] = (k_node, existing_v)
                else:
                    # Value replacement: last wins
                    existing_dict[key] = (k_node, v_node)
            else:
                existing_dict[key] = (k_node, v_node)

        # Reconstruct the list maintaining original order for existing keys
        # and appending new keys at the end.
        new_list = []
        # Keys that appeared originally
        seen_keys = set()
        for k_node, _ in existing_node.value:
            k = k_node.value
            if k in existing_dict and k not in seen_keys:
                new_list.append(existing_dict[k])
                seen_keys.add(k)
        # Remaining new keys
        for key, pair in existing_dict.items():
            if key not in seen_keys:
                new_list.append(pair)
                seen_keys.add(key)

        existing_node.value = new_list

    result_dict = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise TypeError('Each element of nodes must be a tuple of (key_node, value_node)')
        key_node, value_node = item
        if not hasattr(key_node, 'value'):
            raise TypeError('Key node must have a .value attribute')
        key = key_node.value
        if key not in result_dict:
            result_dict[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = result_dict[key]
            if _is_mapping(existing_value_node) and _is_mapping(value_node):
                _merge_mapping_values(existing_value_node, value_node)
                # Keep the new key_node for the key (last wins)
                result_dict[key] = (key_node, existing_value_node)
            else:
                result_dict[key] = (key_node, value_node)

    return list(result_dict.values())

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a parsed Namespace instance via argparse.
    '''
    import argparse
    parser = argparse.ArgumentParser()
    try:
        # No specific arguments are added here; adjust the parser to your needs.
        return parser.parse_args(arguments)
    except SystemExit:
        # argparse uses SystemExit for parsing errors; return None to indicate failure.
        return None

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate input
    if parser is None:
        raise TypeError("parser must not be None")
    # Retrieve the action list (argparse can expose it as 'actions' or '_actions')
    actions = getattr(parser, "actions", None)
    if actions is None:
        actions = getattr(parser, "_actions", None)
    if actions is None:
        raise TypeError("Provided object does not appear to be an argparse.ArgumentParser")
    # Collect all option strings from the actions
    flags = []
    for action in actions:
        # Skip actions that represent positional arguments (no option_strings)
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)
    # Return space-separated flag string
    return " ".join(flags)

def deep_merge_nodes(nodes):
    """
    Merge duplicate mapping keys in a list of (ScalarNode, ValueNode) tuples.
    If a key appears more than once and its values are MappingNodes, merge
    those mappings recursively. For non-mapping values, the last value wins.

    Parameters
    ----------
    nodes : list[tuple]
        List of tuples containing ScalarNode as key and either MappingNode
        or any other node as value.

    Returns
    -------
    list[tuple]
        A new list where duplicate keys are merged as described.

    Raises
    ------
    TypeError
        If `nodes` is not an iterable of tuples with two elements.
    """
    if not isinstance(nodes, (list, tuple)):
        raise TypeError("nodes must be a list or tuple of (key, value) tuples")

    # Helper to merge two lists of mapping entries
    def _merge_mapping_lists(list1, list2):
        merged_dict = {}
        order = []

        def register(key, knode, vnode):
            if key not in merged_dict:
                order.append(key)
            merged_dict[key] = (knode, vnode)

        for knode, vnode in list1:
            if not (hasattr(knode, 'value') and isinstance(knode.value, str)):
                raise TypeError("Key node must have a 'value' attribute of type str")
            register(knode.value, knode, vnode)

        for knode, vnode in list2:
            if not (hasattr(knode, 'value') and isinstance(knode.value, str)):
                raise TypeError("Key node must have a 'value' attribute of type str")
            key = knode.value
            if key in merged_dict:
                old_knode, old_vnode = merged_dict[key]
                if isinstance(old_vnode, MappingNode) and isinstance(vnode, MappingNode):
                    merged_val = MappingNode(
                        old_vnode.tag,
                        _merge_mapping_lists(old_vnode.value, vnode.value)
                    )
                    register(key, old_knode, merged_val)
                else:
                    register(key, knode, vnode)
            else:
                register(key, knode, vnode)

        return [(k, v) for k in order for (_, k_i, v_i) in [merged_dict[k]]]

    merged_entries = {}
    order = []

    for knode, vnode in nodes:
        if not (hasattr(knode, 'value') and isinstance(knode.value, str)):
            raise TypeError("Key node must have a 'value' attribute of type str")
        key = knode.value
        if key in merged_entries:
            existing_knode, existing_vnode = merged_entries[key]
            if isinstance(existing_vnode, MappingNode) and isinstance(vnode, MappingNode):
                merged_val = MappingNode(
                    existing_vnode.tag,
                    _merge_mapping_lists(existing_vnode.value, vnode.value)
                )
                merged_entries[key] = (existing_knode, merged_val)
            else:
                merged_entries[key] = (knode, vnode)
        else:
            merged_entries[key] = (knode, vnode)
            order.append(key)

    # Reconstruct result preserving insertion order
    result = []
    for key in order:
        k, v = merged_entries[key]
        result.append((k, v))
    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic validation: the parser should have the attribute that stores actions.
    if not hasattr(parser, '_actions'):
        raise TypeError('parser must be an argparse.ArgumentParser instance')
    flags = []
    seen = set()
    try:
        for action in parser._actions:
            for flag in getattr(action, 'option_strings', []):
                if flag not in seen:
                    seen.add(flag)
                    flags.append(flag)
        return ' '.join(flags)
    except Exception as exc:
        raise RuntimeError('Failed to extract flags from the ArgumentParser') from exc

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """

    # Validate inputs
    if not isinstance(response, list):
        raise TypeError(f"Expected response to be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"Expected max_results to be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator function
    def _generator():
        try:
            for i in range(0, len(response), max_results):
                yield response[i : i + max_results]
        except Exception as exc:
            # Wrap unexpected errors
            raise RuntimeError("Error while paging through response") from exc

    return _generator()

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable `dicts`.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("The argument 'dicts' must be an iterable of dictionaries")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dictionary, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except Exception as exc:
                    raise TypeError(f"Cannot sum values for key '{key}': {exc}")
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args."""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")
    result = []
    i = 0
    try:
        while i < len(url):
            if url[i] == '{':
                end = url.find('}', i + 1)
                if end == -1:
                    # no closing brace, append the rest as is
                    result.append(url[i:])
                    break
                key = url[i + 1:end]
                if key in url_args:
                    value = url_args[key]
                    if value is None:
                        value = ''
                    result.append(str(value))
                else:
                    # keep placeholder unchanged if key not found
                    result.append('{%s}' % key)
                i = end + 1
            else:
                next_brace = url.find('{', i)
                if next_brace == -1:
                    result.append(url[i:])
                    break
                result.append(url[i:next_brace])
                i = next_brace
    except Exception as exc:
        raise ValueError(f"Error while replacing URL arguments: {exc}") from exc
    return ''.join(result)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if isinstance(val, str):
            stripped = val.strip().lower()
            return stripped in ("none", "null")
        return False
    except Exception:
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    seen = set()
    for action in parser._actions:
        for flag in getattr(action, "option_strings", []):
            if flag and flag not in seen:
                seen.add(flag)
                flags.append(flag)
    return " ".join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Input validation
    if not isinstance(number, int):
        raise TypeError("number must be an int")
    if not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("alphabet must be a list with at least two elements")
    if not all(isinstance(ch, str) for ch in alphabet):
        raise ValueError("all elements of alphabet must be strings")
    if number < 0:
        raise ValueError("number must be non‑negative")
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non‑negative integer")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            digits.append(alphabet[n % base])
            n //= base
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    try:
        return value.replace('.', arg)
    except Exception as exc:
        raise RuntimeError(f"Failed to replace dots: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    # Ensure the argument is a class type
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    # Use a set to avoid duplicates in case of multiple inheritance
    result = set()
    stack = [cls]
    while stack:
        parent = stack.pop()
        try:
            direct = parent.__subclasses__()
        except Exception:
            # If __subclasses__ cannot be accessed, skip this parent
            continue
        for sub in direct:
            if sub not in result:
                result.add(sub)
                stack.append(sub)
    return list(result)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise TypeError("string must be of type str")
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("alphabet must be a non-empty list")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two distinct characters")
    # Create mapping from character to its numeric value
    try:
        digit_map = {char: idx for idx, char in enumerate(alphabet)}
    except Exception as exc:
        raise ValueError("alphabet must consist of unique characters") from exc
    result = 0
    for ch in string:
        if ch not in digit_map:
            raise ValueError(f"Invalid character '{ch}' not in alphabet")
        result = result * base + digit_map[ch]
    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True if macOS
    :rtype: bool
    """
    try:
        if hasattr(os, "uname"):
            return os.uname().sysname == "Darwin"
        return False
    except Exception:
        return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("Input must be a dictionary")
    try:
        result = {}
        for key, value in item.items():
            if isinstance(key, str):
                # Escape the key except for the wildcard '*'
                escaped = re.escape(key)
                regex_key = escaped.replace(r'\*', '.*')
            else:
                regex_key = key
            result[regex_key] = value
        return result
    except Exception as e:
        raise RuntimeError("Error converting dictionary keys to regexes") from e

def unquote(name):
    """Remove quote from the given name."""
    try:
        if not isinstance(name, str):
            return name
        # Remove leading and trailing single or double quotes
        return re.sub(r'^["\']|["\']$', "", name)
    except Exception:
        return name

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    try:
        import os
        import pathlib
        import shutil
        import uuid
    except Exception as e:
        raise RuntimeError(f"Failed to import required modules: {e}") from e

    archive = pathlib.Path(archive_path).expanduser().resolve()
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file does not exist: {archive}")

    tmp_dir = pathlib.Path(tmp_path).expanduser().resolve()
    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Failed to create temporary directory {tmp_dir}: {e}") from e

    # Determine extraction directory name
    if filename:
        extraction_name = filename
    else:
        extraction_name = f"repo_{uuid.uuid4().hex}"
    extraction_dir = tmp_dir / extraction_name

    try:
        extraction_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Failed to create extraction directory {extraction_dir}: {e}") from e

    try:
        shutil.unpack_archive(str(archive), str(extraction_dir))
    except Exception as e:
        raise RuntimeError(f"Failed to unpack archive {archive} into {extraction_dir}: {e}") from e

    # Return as a file URL that can be used as a git origin
    repo_url = f"file://{extraction_dir.as_posix()}"
    return repo_url

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    freq = frequency.strip().lower()
    if freq == "always":
        return None
    import re
    pattern = r'^\s*(?P<value>\d+(?:\.\d+)?)\s*(?P<unit>year|month|week|day|hour|minute|second)s?\s*$'
    match = re.match(pattern, freq, re.IGNORECASE)
    if not match:
        raise ValueError(f"Unrecognized frequency format: '{frequency}'")
    try:
        value = float(match.group('value'))
    except Exception:
        raise ValueError(f"Invalid numeric value in frequency: '{frequency}'")
    unit = match.group('unit').lower()
    kwargs = {}
    if unit == 'year':
        kwargs['days'] = int(round(value * 365))
    elif unit == 'month':
        kwargs['days'] = int(round(value * 30))
    else:
        # map unit to timedelta keyword
        if unit == 'week':
            kwargs['weeks'] = value
        elif unit == 'day':
            kwargs['days'] = value
        elif unit == 'hour':
            kwargs['hours'] = value
        elif unit == 'minute':
            kwargs['minutes'] = value
        elif unit == 'second':
            kwargs['seconds'] = value
    try:
        return datetime.timedelta(**kwargs)
    except Exception as e:
        raise ValueError(f"Could not create timedelta for frequency: '{frequency}'. Reason: {e}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input type
    if not isinstance(host, (str, bytes, bytearray)):
        return False

    # Convert bytes to string if necessary
    try:
        host_str = host.decode() if isinstance(host, (bytes, bytearray)) else host
    except Exception:
        return False

    host_str = host_str.strip()
    if not host_str:
        return False

    # Quick literal checks
    if host_str.lower() == 'localhost':
        return True

    try:
        addr_info = socket.getaddrinfo(host_str, None)
        for entry in addr_info:
            family, _, _, _, sockaddr = entry
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith('127.'):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip in ('::1', '0:0:0:0:0:0:0:1'):
                    return True
        return False
    except Exception:
        # If resolution fails or any other error occurs, conservatively return False
        return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if find_paths is None:
        return []

    try:
        iterator = iter(find_paths)
    except TypeError as exc:
        raise TypeError("find_paths must be an iterable of strings") from exc

    transformed = []
    for item in iterator:
        if not isinstance(item, str):
            raise TypeError(f"Expected string in find_paths, got {type(item).__name__}")
        # Existing pattern? (colon-delimited prefix)
        if ':' in item and re.match(r'^[^:]+:', item):
            transformed.append(item)
        else:
            # Wrap into glob pattern
            transformed.append(f'sh:**/*{item}*/**')
    return transformed

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        addr = ipaddress.ip_address(target)
    except (ValueError, TypeError):
        return False
    return isinstance(addr, ipaddress.IPv4Address)

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    try:
        shape = tuple(shape)
    except Exception as exc:
        raise TypeError("shape must be an iterable of integers representing dimensions.") from exc

    if not shape:
        raise ValueError("shape cannot be empty.")

    for dim in shape:
        if not isinstance(dim, int) or dim < 0:
            raise ValueError(f"shape dimensions must be non-negative integers, got {dim}.")

    # Validate dtype
    try:
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"dtype {dtype} is not a valid numpy dtype.") from exc

    # Attempt to create array
    try:
        arr = np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise RuntimeError(f"Error creating array with shape {shape} and dtype {dtype}: {exc}") from exc

    return arr

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        # Convert input to a NumPy array for vectorized operations
        x_arr = np.asarray(x)
        mu = 0.2
        sigma = 0.1
        # Gaussian value (without normalization factor)
        return np.exp(-((x_arr - mu) ** 2) / (2 * sigma ** 2))
    except Exception as e:
        raise ValueError("Invalid input for gaussian function: " + str(e))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Load and validate each configuration file in the given sequence of filenames.

    Parameters:
        config_filenames (Iterable[str]): Paths to configuration files.
        overrides (dict, optional): Optional dictionary of values to override after loading each configuration.
        resolve_env (bool, optional): If True, perform environment variable substitution on string values
                                      using the pattern ${VAR}.

    Returns:
        tuple[dict[str, dict], list[logging.LogRecord]]: A tuple containing:
            - A dictionary mapping each filename to its parsed configuration dictionary.
            - A list of logging.LogRecord instances for any errors encountered during loading.
    """
    import json
    import os
    import re
    import logging

    configs = {}
    errors = []
    logger = logging.getLogger()

    for filename in config_filenames:
        try:
            with open(filename, 'rb') as f:
                content_bytes = f.read()
            try:
                # Try to decode as UTF-8; if that fails fall back to binary content
                content = content_bytes.decode('utf-8')
            except UnicodeDecodeError:
                # If decoding fails, treat as raw bytes and attempt json loading
                content = content_bytes
        except Exception as e:
            record = logger.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg=f"Failed to read file {filename}: {e}",
                args=(),
                exc_info=e
            )
            errors.append(record)
            continue

        try:
            if isinstance(content, bytes):
                # JSON expects a string, so attempt to decode
                content_str = content.decode('utf-8')
            else:
                content_str = content
            data = json.loads(content_str)
        except Exception as e:
            record = logger.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg=f"Failed to parse JSON in file {filename}: {e}",
                args=(),
                exc_info=e
            )
            errors.append(record)
            continue

        # Resolve environment variables if requested
        if resolve_env:
            def _resolve_env(item):
                if isinstance(item, dict):
                    return {k: _resolve_env(v) for k, v in item.items()}
                if isinstance(item, list):
                    return [_resolve_env(v) for v in item]
                if isinstance(item, str):
                    # Replace ${VAR} with environment variable value
                    return re.sub(r'\${(\w+)}', lambda m: os.getenv(m.group(1), m.group(0)), item)
                return item

            data = _resolve_env(data)

        # Apply overrides if provided
        if overrides and isinstance(overrides, dict):
            if isinstance(data, dict):
                data.update(overrides)
            else:
                record = logger.makeRecord(
                    name=logger.name,
                    level=logging.WARNING,
                    fn=filename,
                    lno=0,
                    msg=f"Overrides provided but configuration in {filename} is not a dict; skipping overrides.",
                    args=(),
                    exc_info=None
                )
                errors.append(record)

        configs[filename] = data

    return configs, errors

def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the internal registry of handlers.  If it does not exist,
    # fall back to an empty dictionary so that the method is still usable.
    handlers = getattr(cls, "_protocol_handlers", {})
    if not isinstance(handlers, dict):
        handlers = {}

    # No explicit version => return a shallow copy of all handlers
    if protocol_version is None:
        return dict(handlers)

    # Validate the type of protocol_version
    if not isinstance(protocol_version, tuple):
        raise TypeError(
            "protocol_version must be a tuple of (major, minor) or None"
        )

    if len(protocol_version) != 2 or not all(isinstance(v, int) for v in protocol_version):
        raise TypeError(
            "protocol_version tuple must contain two integers (major, minor)"
        )

    # Return the handler for the requested version if it exists
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}

    # Unsupported version => return an empty dict
    return {}

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    If *bufsize* is provided, only the first *bufsize* elements are taken when
    converting a non-sequence iterable to a list.
    """
    # Ensure that seq is iterable
    try:
        iter(seq)
    except Exception as exc:
        raise TypeError(f"Object {seq!r} is not iterable") from exc

    # Determine whether seq is already a sequence
    is_sequence = False
    try:
        # A sequence should support length and indexing
        _ = len(seq)
        _ = seq[0]
        is_sequence = True
    except Exception:
        is_sequence = False

    if is_sequence:
        return seq, type(seq)

    # Otherwise, derive a sequence (list) from the iterable
    try:
        if bufsize is not None:
            import itertools
            derived = list(itertools.islice(seq, bufsize))
        else:
            derived = list(seq)
    except Exception as exc:
        raise RuntimeError(f"Failed to derive sequence from {seq!r}") from exc

    return derived, type(derived)

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Basic validation of input
    if hist is None:
        raise ValueError("histogram must not be None")

    # Obtain the list of bins from the histogram
    try:
        bins = hist.get_bins()
    except AttributeError:
        try:
            bins = hist.bins
        except AttributeError:
            raise ValueError("hist must provide bins or get_bins()")
    if not isinstance(bins, (list, tuple)):
        raise ValueError("bins should be a list or tuple of bin objects")

    # Determine the scale to use for the graph
    if scale is True:
        try:
            scale = hist.scale
        except AttributeError:
            scale = None

    # Build the points for the graph
    points = []
    for bin_ in bins:
        # Retrieve bin boundaries
        try:
            left = bin_.left
            right = bin_.right
        except AttributeError:
            raise ValueError("Each bin must have 'left' and 'right' attributes")

        # Compute the coordinate of the point
        if get_coordinate == "left":
            coord = left
        elif get_coordinate == "right":
            coord = right
        elif get_coordinate == "middle":
            coord = (left + right) / 2.0
        else:
            raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

        # Retrieve the bin content
        try:
            content = bin_.content
        except AttributeError:
            # Accept 'value' as an alternative
            try:
                content = bin_.value
            except AttributeError:
                raise ValueError("Each bin must have a numeric content")

        # Convert content to graph values
        if make_value is not None:
            try:
                value = make_value(content)
            except Exception as exc:
                raise ValueError(f"make_value raised an exception: {exc}") from exc
        else:
            value = content

        # Ensure value is tuple-like for compatibility
        if isinstance(value, (list, tuple)):
            value_tuple = tuple(value)
        else:
            value_tuple = (value,)

        # Construct the point in the format (coord, value, ...)
        point = (coord,) + value_tuple
        points.append(point)

    # Validate that the number of fields matches the dimension of the points
    if points:
        expected_fields = len(points[0])
        if len(field_names) != expected_fields:
            raise ValueError(f"field_names length ({len(field_names)}) does not match "
                             f"point dimension ({expected_fields})")
    else:
        # No bins -> still return empty graph with provided field names
        field_names = field_names

    # Return the graph representation as a simple dictionary
    return {
        "points": points,
        "field_names": field_names,
        "scale": scale
    }

