    """
    Verify that *candidate* might correctly provide *iface*.

def verifyObject(iface, candidate, tentative=False):
    """Verify that *candidate* might correctly provide *iface*."""
    errors = []
    try:
        import inspect
    except Exception:
        inspect = None

    # 1. Check that candidate claims to provide iface (unless tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate does not provide interface {iface.__name__}")
        except Exception as e:
            errors.append(f"Error checking providedBy: {e}")

    # 2. Ensure all required interface names are present on candidate
    names = getattr(iface, "names", lambda: set())()
    for name in names:
        iface_attr = iface.__dict__.get(name, None)
        candidate_attr = getattr(candidate, name, None)

        if candidate_attr is None:
            errors.append(f"Missing required attribute or method '{name}'")
            continue

        # If interface defines a callable (method), check signature compatibility
        if (
            iface_attr
            and callable(iface_attr)
            and inspect
        ):
            try:
                iface_sig = inspect.signature(iface_attr)
                cand_sig = inspect.signature(candidate_attr)
                if str(iface_sig) != str(cand_sig):
                    errors.append(
                        f"Signature mismatch for method '{name}': "
                        f"expected {iface_sig}, got {cand_sig}"
                    )
            except Exception:
                # Unable to introspect signatures; skip check
                pass

    # 3. Report errors if any
    if errors:
        from zope.interface import Invalid

        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # Validate that bases are all types
    for i, b in enumerate(bases):
        if not isinstance(b, type):
            raise TypeError(f"Base class at position {i} ({b!r}) is not a type")
    # Validate explicit metaclass if given
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a type")
        # Must be a subclass of all base metaclasses
        for i, b in enumerate(bases):
            base_meta = type(b)
            if not issubclass(explicit_mc, base_meta):
                raise TypeError(
                    f"Explicit metaclass {explicit_mc.__name__} is not a subclass of "
                    f"base metaclass {base_meta.__name__} for base {b!r}"
                )
        return explicit_mc
    # No explicit metaclass: determine from bases
    if not bases:
        return type
    # Start with metaclass of first base
    candidate = type(bases[0])
    for i, b in enumerate(bases[1:], start=1):
        base_meta = type(b)
        if not issubclass(candidate, base_meta):
            if issubclass(base_meta, candidate):
                candidate = base_meta
            else:
                raise TypeError(
                    f"Metaclass conflict: {candidate.__name__} is not a subclass of "
                    f"{base_meta.__name__} (for base at position {i})"
                )
    return candidate

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # The LRU cache is assumed to store entries in an OrderedDict
    # where the oldest entry (least recently used) is at the beginning.
    try:
        # Try to pop the oldest item
        key, value = self._cache.popitem(last=False)
        return (key, value)
    except AttributeError as e:
        # If the expected internal cache does not exist raise an informative error
        raise AttributeError("The LRU cache instance lacks a `_cache` attribute.") from e
    except KeyError:
        # Raised when attempting to pop from an empty container
        raise KeyError("Attempted to popitem from an empty LRU cache.")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key = next(reversed(self))
    except StopIteration:
        raise KeyError('popitem from an empty collection')
    value = self[key]
    del self[key]
    return key, value

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        data = getattr(self, "_data")
    except AttributeError:
        raise AttributeError("The object lacks a '_data' attribute required for popitem")
    if not isinstance(data, dict):
        raise TypeError("popitem expects a dict-like '_data' attribute")
    if not data:
        raise KeyError("popitem(): dictionary is empty")
    import random
    key = random.choice(list(data.keys()))
    value = data[key]
    del data[key]
    return key, value

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        import re
        # Matches strings like "param in [value1, value2]" with optional whitespace
        pattern_str = r'^\s*(?P<name>\w+)\s+in\s*\[\s*(?P<values>[^]]+)\s*\]\s*$'
        return re.compile(pattern_str, re.IGNORECASE)
    except Exception as exc:
        raise RuntimeError(f"Unable to construct the 'in' regex pattern: {exc}") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Handle None or malformed inputs gracefully
    if request is None:
        return False

    # Helper to safely access attributes or dict keys
    def _has_flag(attr_name: str) -> bool:
        try:
            # Try attribute access
            if hasattr(request, attr_name):
                return bool(getattr(request, attr_name))
            # Try dictionary key access
            if isinstance(request, dict):
                return bool(request.get(attr_name))
        except Exception:
            pass
        return False

    # 1. Public message check
    if _has_flag("public"):
        return True

    # 2. Private message check
    if _has_flag("private"):
        return True

    # 3. Legacy payload check
    if _has_flag("legacy"):
        return True

    # Not identified as a Diaspora request
    return False

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    # Basic validation
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if replacer is not None and not callable(replacer):
        raise TypeError("replacer must be a callable")

    import re

    # Regex to split out fenced code blocks (` ``` ... ``` `)
    code_block_pattern = re.compile(r"```.*?```", re.DOTALL)
    parts = code_block_pattern.split(text)

    tags: Set[str] = set()
    result_parts: list[str] = []

    def _replace_tag(match: re.Match) -> str:
        tag = match.group(1)
        tags.add(tag)
        if replacer:
            try:
                return replacer(tag)
            except Exception:
                # If replacer fails, fallback to original match
                return match.group(0)
        return match.group(0)

    # Iterate over parts: even indices are normal text, odd are code blocks
    for idx, part in enumerate(parts):
        if idx % 2 == 0:
            # Process normal text for tags
            processed = re.sub(r"@(\w+)", _replace_tag, part)
            result_parts.append(processed)
        else:
            # Code block: leave untouched
            result_parts.append(part)

    replaced_text = "".join(result_parts)
    return tags, replaced_text

