    if not isinstance(tag, str):
        return False

    # Tag must be non-empty
    if not tag:
        return False

    # Tag should only contain letters, digits, hyphens, or underscores
    allowed_chars = set("-_")
    for char in tag:
        if not (char.isalnum() or char in allowed_chars):
            return False

    # Optionally, ensure at least one letter is present (to avoid numeric-only tags)
    if not any(char.isalpha() for char in tag):
        return False

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Basic input validation: xml Element-like objects should have a .tag
    if not hasattr(node, 'tag'):
        raise TypeError("Expected XML element-like node with 'tag' attribute")
    result = {}
    try:
        for child in node:
            if not hasattr(child, 'tag'):
                continue
            tag = child.tag
            if tag in result:
                existing = result[tag]
                if isinstance(existing, list):
                    existing.append(child)
                else:
                    result[tag] = [existing, child]
            else:
                result[tag] = child
    except Exception as exc:
        # In case of unexpected structure or iteration issues, raise a descriptive error
        raise RuntimeError(f"Failed to process children of node '{node}': {exc}") from exc
    return result

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Basic type checking
    if not isinstance(public_key, str):
        raise TypeError("public_key must be a string")
    if not isinstance(doc, str):
        raise TypeError("doc must be a string")
    if not isinstance(signature, str):
        raise TypeError("signature must be a string")

    try:
        # The signature is expected to be a base64-encoded SHA-256 hash of the document
        decoded_sig = __import__('base64').b64decode(signature)
    except Exception:
        # Invalid base64 encoding
        return False

    try:
        # Compute SHA-256 digest of the document
        digest = __import__('hashlib').sha256(doc.encode('utf-8')).digest()
    except Exception:
        return False

    # Compare the computed digest with the decoded signature
    return decoded_sig == digest

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Import inside to avoid top‑level side effects
    try:
        import json
        import xml.etree.ElementTree as ET
    except Exception:
        return {}

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except Exception:
        pass

    # Fallback to XML parsing (XRD)
    try:
        root = ET.fromstring(document)
    except Exception:
        return {}

    def strip_ns(tag: str) -> str:
        return tag.split("}")[-1] if "}" in tag else tag

    result: Dict[str, object] = {}

    for child in root:
        tag = strip_ns(child.tag)
        if tag == "Subject":
            if child.text:
                result["subject"] = child.text.strip()
        elif tag == "Alias":
            if child.text:
                result.setdefault("aliases", []).append(child.text.strip())
        elif tag == "Link":
            link: Dict[str, str] = {}
            for attr in ("rel", "type", "href", "template"):
                val = child.get(attr)
                if val:
                    link[attr] = val
            if link:
                result.setdefault("links", []).append(link)
        elif tag == "Property":
            name = child.attrib.get("name")
            if name and child.text is not None:
                result.setdefault("properties", {})[name] = child.text

    return result

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate input
    if not isinstance(handle, str) or not handle.strip():
        return {}
    handle = handle.strip()
    # Handle basic format check
    if '@' not in handle:
        return {}

    # Build the webfinger URL
    try:
        from urllib import request, parse
        import json
    except Exception:
        # If import fails, return empty result
        return {}

    try:
        # Properly URL-encode the resource parameter
        resource = f'acct:{handle}'
        params = parse.urlencode({'resource': resource})
        # Extract domain part for the URL
        _, domain = handle.split('@', 1)
        url = f'https://{domain}/.well-known/webfinger?{params}'

        # Perform the GET request with a timeout
        with request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                return {}
            data = resp.read()
        # Decode and parse JSON
        try:
            content = data.decode('utf-8')
            result = json.loads(content)
            if isinstance(result, dict):
                return result
            else:
                return {}
        except Exception:
            return {}
    except Exception:
        return {}

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Validate input
    if not isinstance(host, str) or not host.strip():
        raise ValueError("host must be a non-empty string")

    # Normalize host: strip any scheme or path
    try:
        from urllib.parse import urlparse
    except ImportError as exc:
        raise RuntimeError("Failed to import urllib.parse") from exc

    parsed = urlparse(host.strip())
    netloc = parsed.netloc if parsed.netloc else parsed.path
    if not netloc:
        raise ValueError("Invalid host value")

    # Build potential URLs to try
    schemes = ["https", "http"]
    urls = [f"{scheme}://{netloc}/.well-known/host-meta" for scheme in schemes]

    # Import requests lazily
    try:
        import requests
    except ImportError as exc:
        raise RuntimeError("requests library is required to fetch host-meta") from exc

    exception = None
    response = None
    for url in urls:
        try:
            response = requests.get(url, timeout=10)
            response.raise_for_status()
            break  # success
        except requests.RequestException as exc:
            exception = exc
            continue  # try next scheme

    if response is None:
        raise RuntimeError(f"Failed to fetch host-meta from {netloc}") from exception

    # Parse the XML content
    try:
        import xml.etree.ElementTree as ET
    except ImportError as exc:
        raise RuntimeError("xml.etree.ElementTree is required to parse host-meta") from exc

    try:
        root = ET.fromstring(response.content)
    except ET.ParseError as exc:
        raise ValueError("The retrieved host-meta document is not valid XML") from exc

    # Return the root element as the XRD instance
    return root

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Validate settings_dirs
    if settings_dirs is None:
        return []
    try:
        # Ensure we have an iterable of directories
        dirs_iter = iter(settings_dirs)
    except TypeError:
        # Not iterable; raise
        raise TypeError("settings_dirs must be an iterable of directory paths")

    import os
    import fnmatch

    result = []

    # Normalize spec_option: allow None or empty string to mean all files
    if spec_option is None or spec_option == "":
        use_glob = False
        spec = None
    else:
        # Determine if spec_option contains glob pattern characters
        if any(ch in spec_option for ch in "*?[]"):
            use_glob = True
            spec = spec_option
        else:
            use_glob = False
            spec = spec_option

    for dir_path in dirs_iter:
        # Skip if dir_path is None or empty
        if not dir_path:
            continue
        if not isinstance(dir_path, str):
            # skip invalid path entries
            continue
        try:
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                if use_glob:
                    if fnmatch.fnmatch(entry, spec):
                        result.append(full_path)
                else:
                    if spec is None or entry.endswith(spec):
                        result.append(full_path)
        except (OSError, PermissionError):
            # Skip directories that cannot be accessed
            continue

    return result

def ansible_config_manager(cls):
    """Gets the ansible config manager."""
    try:
        from ansible.config.manager import AnsibleConfig
        return AnsibleConfig()
    except Exception:
        # If Ansible or its config manager is not available, return None
        return None

def workspace_manager(cls):
    """Gets the workspace manager. """
    try:
        return cls._workspace_manager
    except AttributeError as e:
        raise AttributeError(f"Workspace manager not configured for class {cls.__name__}") from e

def validate_from_file(cls, yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("The yaml_file argument must be provided")

    try:
        import yaml
    except ImportError as exc:
        raise IRValidatorException(f"YAML parser is not available: {exc}") from exc

    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise IRValidatorException(f"YAML file does not exist: {yaml_file}")
    except Exception as exc:
        raise IRValidatorException(f"Error reading YAML file {yaml_file}: {exc}") from exc

    if not isinstance(data, dict):
        raise IRValidatorException(f"YAML file {yaml_file} does not contain a mapping at the top level")

    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    if not isinstance(required_fields, (list, set, tuple)):
        raise IRValidatorException("Class attribute REQUIRED_FIELDS must be a list, set, or tuple")

    missing_fields = [field for field in required_fields if field not in data]
    if missing_fields:
        raise IRValidatorException(
            f"Missing required fields in {yaml_file}: {', '.join(missing_fields)}"
        )

    return data

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.
    Attempts to collect default values from a `spec` mapping defined on the instance,
    optionally overridden by values supplied in an `overrides` mapping or from
    environment variables. Returns a dictionary of resolved defaults.
    """
    try:
        # Retrieve spec and overrides from the instance; fall back to empty dicts if absent
        spec = getattr(self, 'spec', {})
        overrides = getattr(self, 'overrides', {})
        if not isinstance(spec, dict):
            raise TypeError("`spec` attribute must be a dictionary")
        if not isinstance(overrides, dict):
            overrides = {}

        resolved = {}
        for key, descriptor in spec.items():
            # Support plain default values
            if isinstance(descriptor, dict):
                default = descriptor.get('default')
                # Optional type conversion
                typ = descriptor.get('type')
            else:  # plain value
                default = descriptor
                typ = None

            # Try to override from `overrides`
            if key in overrides:
                value = overrides[key]
                # Convert type if needed
                if typ and not isinstance(value, typ):
                    try:
                        value = typ(value)
                    except Exception:
                        # If conversion fails, keep the original override value
                        pass
                resolved[key] = value
            elif default is not None:
                # Convert default to declared type if necessary
                if typ and not isinstance(default, typ):
                    try:
                        resolved[key] = typ(default)
                    except Exception:
                        # Fall back to the raw default if conversion fails
                        resolved[key] = default
                else:
                    resolved[key] = default
            else:
                # No default and no override; skip this key
                continue

        return resolved

    except Exception as exc:
        # Convert any error into a RuntimeError with context
        raise RuntimeError(f"Failed to resolve spec defaults: {exc}") from exc

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Try to fetch the parser associated with the command name.  The
    # parser is expected to be stored in a dictionary attribute named
    # ``parsers`` or ``commands``.  If the attribute is missing or the
    # command name is not found, raise a ValueError so callers know the
    # input was invalid.
    parser = None
    if hasattr(self, "parsers"):
        parser = self.parsers.get(command_name)
    elif hasattr(self, "commands"):
        parser = self.commands.get(command_name)

    if parser is None:
        raise ValueError(f"Unsupported or unknown command: {command_name}")

    # Build a list of option strings.  We handle any parser types that
    # expose a ``_actions`` attribute (argparse) or a ``option_list``
    # (optparse).  Keeping the fallback logic makes the method robust
    # across different parser implementations.
    options = []

    if hasattr(parser, "_actions"):
        for action in parser._actions:
            try:
                opts = action.option_strings
            except AttributeError:
                # Some action objects might provide a single string via ``option_string``
                opts = [getattr(action, "option_string", None)]
            # Filter out None or empty strings.
            for opt in opts:
                if isinstance(opt, str) and opt not in (None, ""):
                    options.append(opt)
    elif hasattr(parser, "option_list"):
        # Deprecated optparse style.
        for opt in parser.option_list:
            if hasattr(opt, "get_opt_strings"):
                opts = opt.get_opt_strings()
                if isinstance(opts, str):
                    opts = [opts]
            else:
                opts = [getattr(opt, "flag_str", None)]
            for o in opts:
                if isinstance(o, str) and o not in (None, ""):
                    options.append(o)

    # Normalise the output: remove duplicates while preserving order.
    seen = set()
    uniq_options = []
    for opt in options:
        if opt not in seen:
            seen.add(opt)
            uniq_options.append(opt)

    return uniq_options

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []

    # Ensure options_spec is iterable
    try:
        iter_options = iter(options_spec)
    except Exception:
        return required_args

    # args may be None, wrap into dict for safety
    if args is None:
        args = {}

    for opt in iter_options:
        try:
            # Spec objects may be dict-like or have attributes
            name = opt.get("name") if isinstance(opt, dict) else getattr(opt, "name", None)
            if not name:
                continue

            cond = (
                opt.get("required_when")
                if isinstance(opt, dict)
                else getattr(opt, "required_when", None)
            )
            if cond is None:
                continue

            condition_matched = False

            if callable(cond):
                try:
                    condition_matched = bool(cond(command_name, args))
                except Exception:
                    condition_matched = False
            elif isinstance(cond, dict):
                # Possibly a mapping of command names to booleans or callables
                if command_name in cond:
                    val = cond[command_name]
                    if callable(val):
                        try:
                            condition_matched = bool(val(command_name, args))
                        except Exception:
                            condition_matched = False
                    else:
                        condition_matched = bool(val)
            elif isinstance(cond, (list, set, tuple)):
                # List or set of command names requiring this arg
                condition_matched = command_name in cond
            elif isinstance(cond, str):
                condition_matched = command_name == cond
            else:
                # Fallback: interpret truthy value
                condition_matched = bool(cond)

            if condition_matched:
                required_args.append(name)
        except Exception:
            # Silently ignore malformed option specs
            continue

    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure the arguments are a dictionary of key/value pairs.
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # Get the length specification mapping from the instance if present.
    length_spec = getattr(self, "length_spec", None)
    if not isinstance(length_spec, dict):
        # No length restrictions are defined; nothing to validate.
        return

    # Iterate through each argument and validate its length against the spec.
    for key, value in args.items():
        # Skip arguments that are not in the length spec.
        if key not in length_spec:
            continue

        max_len = length_spec[key]
        # Only integer max lengths are meaningful; otherwise skip.
        if not isinstance(max_len, int) or max_len < 0:
            continue

        try:
            # Convert non‑string values to string before measuring length.
            val_len = len(str(value))
        except Exception:
            # If the value is somehow not measurable, ignore it in this check.
            continue

        if val_len > max_len:
            raise ValueError(
                f"Argument '{key}' has length {val_len}, "
                f"which exceeds the maximum allowed length of {max_len}"
            )

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    try:
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")
        if not isinstance(spec_option, dict):
            raise ValueError("spec_option must be a dictionary")
    except Exception as exc:
        raise ValueError(f"Invalid parameters for creating complex type: {exc}") from exc

    # Define a simple complex argument type holder
    class ComplexArgumentType:
        __slots__ = ("subcommand", "type_name", "option_name", "spec_option")

        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec_option = spec_option

        def __repr__(self):
            return (f"<ComplexArgumentType {self.type_name!r} for "
                    f"{self.subcommand!r}:{self.option_name!r} with spec {self.spec_option!r}>")

    # Instantiate the complex argument type
    try:
        complex_type = ComplexArgumentType(subcommand, type_name,
                                            option_name, spec_option)
    except Exception as exc:
        raise RuntimeError(f"Failed to instantiate complex type: {exc}") from exc

    # Cache the instance if a registry exists
    try:
        registry = getattr(self, "_complex_type_registry", None)
        if registry is None:
            registry = {}
            self._complex_type_registry = registry
        key = (subcommand, type_name)
        registry[key] = complex_type
    except Exception:
        # Non-critical – just ignore caching failures
        pass

    return complex_type

def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or tuple")
    for item in extra_vars:
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, str):
            stripped = item.strip()
            if not stripped or '=' not in stripped:
                # Skip malformed strings
                continue
            key, value = stripped.split('=', 1)
            vars_dict[key] = value
        else:
            # Unsupported type; ignore
            continue
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke (relative to the workspace root or an absolute path)
    :param verbose: Ansible verbosity level (integer, 0-4)
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    :return: subprocess.CompletedProcess instance containing the ansible-playbook invocation results
    """

    # Ensure the playbook exists
    try:
        if not isinstance(playbook_path, str):
            raise TypeError("playbook_path must be a string")
        import os
        # Resolve the absolute path
        playbook_abs = os.path.join(ir_workspace.root, playbook_path)
        if not os.path.isfile(playbook_abs):
            raise FileNotFoundError(f"Playbook not found: {playbook_abs}")
    except Exception as exc:
        raise RuntimeError(f"Failed to validate playbook path: {exc}") from exc

    # Basic command construction
    cmd = ["ansible-playbook"]

    # Verbosity flag
    try:
        if verbose is not None:
            if not isinstance(verbose, int):
                raise TypeError("verbose must be an integer")
            if verbose < 0 or verbose > 4:
                raise ValueError("verbose must be between 0 and 4 inclusive")
            if verbose > 0:
                cmd.extend(["-v"] * verbose)
    except Exception as exc:
        raise RuntimeError(f"Failed to process verbosity level: {exc}") from exc

    # Add the playbook path
    cmd.append(playbook_abs)

    # Plug in ansible_args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for flag, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    # Boolean flag, just add the flag name
                    cmd.append(f"--{flag}")
                else:
                    # Skip false boolean flags
                    continue
            elif value is None:
                # Skip None values
                continue
            else:
                # For arguments that require a value, pass as --key=value
                cmd.append(f"--{flag}={value}")

    # Extra vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            import json
            extra_json = json.dumps(extra_vars)
            cmd.extend(["--extra-vars", extra_json])
        except Exception as exc:
            raise RuntimeError(f"Failed to serialize extra_vars to JSON: {exc}") from exc

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False
        )
    except FileNotFoundError as fnf_error:
        raise RuntimeError("ansible-playbook executable not found. Ensure Ansible is installed.") from fnf_error
    except Exception as exc:
        raise RuntimeError(f"Error invoking ansible-playbook: {exc}") from exc

    # Log the output if verbose or ir_plugin provides a logger
    try:
        if ir_plugin and hasattr(ir_plugin, "log"):
            ir_plugin.log(f"ansible-playbook command: {' '.join(cmd)}")
            ir_plugin.log(f"stdout: {result.stdout}")
            ir_plugin.log(f"stderr: {result.stderr}")
    except Exception:
        # Non-critical: ignore logging errors
        pass

    return result

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Validate input types
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list")
    if not isinstance(ir_workspace, object):
        raise TypeError("ir_workspace must be an object")
    if not isinstance(ir_plugin, object):
        raise TypeError("ir_plugin must be an object")

    # Build the ansible-playbook command
    command = ["ansible-playbook"] + cli_args

    # Serialize vars_dict to JSON for --extra-vars
    json_module = __import__("json")
    try:
        extra_vars = json_module.dumps(vars_dict)
    except Exception as e:
        raise ValueError(f"Failed to serialize vars_dict to JSON: {e}")

    command += ["--extra-vars", extra_vars]

    # Execute the command
    subprocess = __import__("subprocess")
    try:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError:
        # ansible-playbook binary not found
        return {
            "rc": -1,
            "stdout": "",
            "stderr": "ansible-playbook command not found. Is Ansible installed?",
        }
    except Exception as e:
        return {"rc": -1, "stdout": "", "stderr": f"Execution failed: {e}"}

    # Return the result in a plain dictionary
    return {"rc": result.returncode, "stdout": result.stdout, "stderr": result.stderr}

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in-place.
    Supports boolean, integer, float, and comma‑separated lists.

    Args:
        parser_name (str): The command name being processed.
        values_dict (dict): Mapping of argument names to string values.

    Returns:
        dict: The same dictionary object with values converted to native types.
    """
    if values_dict is None:
        raise ValueError("values_dict must not be None")

    import re

    for key, raw_value in list(values_dict.items()):
        if raw_value is None:
            continue
        if not isinstance(raw_value, str):
            # nothing to convert if not a string
            continue

        value = raw_value.strip()

        # Handle empty strings as None
        if value == "":
            values_dict[key] = None
            continue

        lowered = value.lower()

        # Boolean conversion
        if lowered in {"true", "false", "yes", "no", "y", "n", "1", "0", "on", "off"}:
            values_dict[key] = lowered in {"true", "yes", "y", "1", "on"}
            continue

        # Integer conversion
        if re.fullmatch(r"[+-]?\d+", value):
            try:
                values_dict[key] = int(value)
                continue
            except ValueError:
                pass

        # Float conversion
        if re.fullmatch(r"[+-]?(\d+\.\d*|\.\d+)([eE][+-]?\d+)?", value) or \
           re.fullmatch(r"[+-]?\d+[eE][+-]?\d+", value):
            try:
                values_dict[key] = float(value)
                continue
            except ValueError:
                pass

        # Comma‑separated list handling
        if "," in value:
            parts = [p.strip() for p in value.split(",")]
            converted_list = []

            for part in parts:
                part_lower = part.lower()
                if part_lower in {"true", "false", "yes", "no", "y", "n", "1", "0", "on", "off"}:
                    converted_list.append(part_lower in {"true", "yes", "y", "1", "on"})
                elif re.fullmatch(r"[+-]?\d+", part):
                    try:
                        converted_list.append(int(part))
                        continue
                    except ValueError:
                        pass
                elif re.fullmatch(r"[+-]?(\d+\.\d*|\.\d+)([eE][+-]?\d+)?", part) or \
                     re.fullmatch(r"[+-]?\d+[eE][+-]?\d+", part):
                    try:
                        converted_list.append(float(part))
                        continue
                    except ValueError:
                        pass
                else:
                    converted_list.append(part)

            values_dict[key] = converted_list
            continue

        # Fallback: keep the original string
        values_dict[key] = value

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Local imports to avoid global namespace pollution
    try:
        import os
        import json
    except Exception as exc:  # pragma: no cover
        raise RuntimeError("Required modules 'os' and 'json' could not be imported") from exc

    # Validate input
    if not isinstance(plugin_dir, str):
        raise ValueError(f"plugin_dir must be a string path, got {type(plugin_dir).__name__}")
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"Provided plugin_dir '{plugin_dir}' is not a directory or does not exist")

    # Determine the spec file to read
    possible_files = ['plugin.json', 'plugin_spec.json', 'spec.json', 'plugin.yaml', 'plugin.yml']
    spec_path = None
    for fname in possible_files:
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'. "
                                f"Tried: {', '.join(possible_files)}")

    # Load the spec contents
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            if spec_path.endswith(('.yaml', '.yml')):
                # Try to use yaml if available
                try:
                    import yaml  # pragma: no cover
                except Exception:
                    raise RuntimeError("YAML support is required for .yaml/.yml spec files but yaml module is missing")
                data = yaml.safe_load(f)
            else:
                data = json.load(f)
    except Exception as exc:  # pragma: no cover
        raise ValueError(f"Failed to parse plugin spec file '{spec_path}': {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError(f"Plugin spec in '{spec_path}' does not contain a top-level dictionary")

    # Recursive flattening
    def _flatten(curr, parent_key="", sep="."):
        items = {}
        for k, v in curr.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        os = __import__('os')
        var_name = 'CONFIG_PATH'
        if not os.environ.get(var_name):
            default_path = os.path.join(os.path.dirname(__file__), 'config.yaml')
            os.environ[var_name] = default_path
    except Exception:
        # Silently ignore any issues (e.g., missing os module or permission errors)
        pass
